namespace {
QString esc(const QVariant&v){return v.toString().toHtmlEscaped().replace("\n","<br/>");}
QString text(const QVariantMap&m,const char*k){auto s=m.value(k).toString().trimmed();return s.isEmpty()?QStringLiteral("未提供"):esc(s);}
QString para(const QVariant &v){return "<p>"+esc(v)+"</p>";}
QString row(const QString&a,const QString&b){return "<tr><td width='26%' bgcolor='#F0F3F7'>"+a+"</td><td>"+b+"</td></tr>";}
QString table(const QString &s){return "<table width='100%' border='1' cellspacing='0' cellpadding='5'>"+s+"</table>";}
QString hash(const QString &p){QFile f(p);if(!f.open(QIODevice::ReadOnly))return {};QCryptographicHash h(QCryptographicHash::Sha256);if(!h.addData(&f))return {};return QString::fromLatin1(h.result().toHex());}
QString date(const QVariant &v){auto dt=QDateTime::fromString(v.toString(),Qt::ISODate);return dt.isValid()?dt.toLocalTime().toString("yyyy-MM-dd HH:mm:ss"):esc(v);}
}
