 QFile file(path);if(!file.open(QIODevice::ReadOnly)||file.size()>2000000)return 2;auto snapshot=QJsonDocument::fromJson(file.readAll()).toVariant().toMap();auto form=snapshot.value("form").toMap(),result=snapshot.value("result").toMap();const auto images=snapshot.value("images").toList(),sources=snapshot.value("sources").toList();
