 html+="<h1>设备运行声学特征与异常评价报告</h1><p align='center'>"+esc(snapshot.value("id"))+" / V"+esc(snapshot.value("revision"))+" · "+(snapshot.value("status")=="reviewed"?"已审核":"待审核草稿")+"</p>";
 html+=table(row("设备名称 / 编号",text(form,"device")+" / "+text(form,"device_code"))+row("现场 / 测点",text(form,"site")+" / "+text(form,"point"))+row("委托方",text(form,"client"))+row("报告单位 / 地址",text(form,"organization")+" / "+text(form,"organization_address"))+row("报告目的","设备运行声学特征描述、异常线索评价与复核建议")+row("编制人 / 初版日期",text(snapshot,"author")+" / "+date(snapshot.value("created_at")))+row("审核人 / 审核日期",snapshot.value("status")=="reviewed"?text(snapshot,"reviewer")+" / "+date(snapshot.value("reviewed_at")):"待实际授权账号复核")+row("本版时间 / 软件版本",date(snapshot.value("version_at"))+" / "+text(snapshot,"application_version")));
