 auto channelMetrics=snapshot.value("channel_metrics").toList();QString metricTable="<tr><th>通道</th><th>RMS / FS</th><th>峰值 / FS</th><th>峰值因子</th><th>峭度</th><th>削顶 / %</th></tr>";
 for(auto v:channelMetrics){auto m=v.toMap();metricTable+="<tr><td>"+esc(m["channel"])+"</td>";for(auto key:{"rms","peak","crest","kurtosis","clipped_pct"})metricTable+="<td>"+(m.value(key).isNull()?QStringLiteral("不适用"):QString::number(m.value(key).toDouble(),'g',4))+"</td>";metricTable+="</tr>";}html+=table(metricTable);
 html+="<p>计算说明："+text(snapshot,"processing")+"</p>";html+=table(row("完整计算结果 SHA-256","<small>"+text(snapshot,"analysis_data_sha256")+"</small>"));
 auto failures=snapshot.value("analysis_errors").toList();if(!failures.isEmpty()){QString f="<tr><th>方法</th><th>通道</th><th>未得到有效结果的原因</th></tr>";for(auto v:failures){auto e=v.toMap();f+="<tr><td>"+esc(e["method"])+"</td><td>"+esc(e["channel"])+"</td><td>"+esc(e["error"])+"</td></tr>";}html+=table(f);}

 for(auto v:sources){auto s=v.toMap();html+=table(row("录音标识 / 来源",text(s,"id")+" / "+text(s,"origin"))+row(s.value("origin")=="imported"?QStringLiteral("导入时间（原采集日期未核验）"):QStringLiteral("采集开始时间"),QDateTime::fromMSecsSinceEpoch(qRound64(s.value("started").toDouble()*1000)).toLocalTime().toString("yyyy-MM-dd HH:mm:ss"))+row("采样率 / 通道 / 整段时长",QString::number(s.value("fs").toInt())+" Hz / "+QString::number(s.value("channels").toInt())+" / "+QString::number(s.value("duration").toDouble(),'f',0)+" s")+row("可解释频带上限",QString::number(s.value("fs").toDouble()/2000,'g',3)+" kHz（奈奎斯特上限，不代表已校准响应带宽）")+row("文件 SHA-256","<small>"+text(s,"sha256")+"</small>"));html+="<p></p>";}
 int figure=0;for(auto v:images){auto c=v.toMap(),m=c.value("metadata").toMap(),plot=m.value("plot").toMap();html+="<p><b>F"+QString::number(++figure)+" · "+esc(c.value("title"))+"</b> · 通道 "+esc(m.value("channel"))+" · "+text(m,"unit")+" · 分析范围 "+text(m,"analysis_scope")+" · "+text(m,"analysis_start")+"–"+text(m,"analysis_end")+" s</p>";
 auto metrics=plot.value("metrics").toMap();if(!metrics.isEmpty()){QString rows="<tr><th>计算指标</th><th>原始计算值（单位由指标定义）</th></tr>";for(auto it=metrics.begin();it!=metrics.end();++it)if(it.value().canConvert<double>())rows+="<tr><td>"+it.key().toHtmlEscaped()+"</td><td>"+QString::number(it.value().toDouble(),'g',5)+"</td></tr>";html+=table(rows);}}
