 html+="<h2>六、综合评价与结论</h2>"+para(result.value("assessment"))+table(row("评价等级",text(result,"level"))+row("AI 辅助结论",text(result,"conclusion")));
 if(!snapshot.value("editorial_conclusion").toString().isEmpty())html+="<p><b>人工确认 / 更正结论</b></p>"+para(snapshot.value("editorial_conclusion"));
 html+="<p><b>复核与处置建议</b></p><ol>";for(auto v:result.value("recommendations").toList())html+="<li>"+esc(v)+"</li>";html+="</ol><p><b>限制与不确定性</b></p>"+para(result.value("limitations"));
 html+="<h2>七、审核、更正与可追溯记录</h2>"+table(row("本版状态",snapshot.value("status")=="reviewed"?"已审核":"待审核草稿；AI 意见须经人员复核")+row("编制人账号",text(snapshot,"author"))+row("审核人账号",text(snapshot,"reviewer"))+row("复核说明",text(snapshot,"review_note"))+row("更正原因",text(snapshot,"correction_reason"))+row("模型 / 提示词版本",text(snapshot,"model")+" / "+text(snapshot,"prompt_version"))+row("报告快照 SHA-256","<small>"+hash(path)+"</small>"));
 html+="<p>各版报告分别保存，旧版不会被覆盖。导出 PDF 以本版冻结图表和原始录音校验值为依据；使用者应保存原始证据与对应版本。不得将部分内容作为独立达标证明。</p>";
 figure=0;for(auto v:images){auto c=v.toMap(),m=c.value("metadata").toMap(),plot=m.value("plot").toMap();auto imagePath=c.value("path").toString();QImageReader reader(imagePath);auto size=reader.size();if(!size.isValid())return 5;size.scale(640,385,Qt::KeepAspectRatio);
 html+="<h2 style='page-break-before:always'>附录 F"+QString::number(++figure)+" · "+esc(c.value("title"))+"</h2><p align='center'><img src='"+QUrl::fromLocalFile(imagePath).toString().toHtmlEscaped()+"' width='"+QString::number(size.width())+"' height='"+QString::number(size.height())+"'/></p>";
 html+=table(row("图表 / 通道",esc(c.value("title"))+" / "+esc(m.value("channel")))+row("坐标与单位",text(plot,"x_label")+"；"+text(plot,"y_label"))+row("分析区间",text(m,"analysis_scope")+" / "+text(m,"analysis_start")+"–"+text(m,"analysis_end")+" s")+row("冻结时间",date(m.value("captured_at")))+row("图表 SHA-256","<small>"+text(c,"sha256")+"</small>"));
 html+="<p>图表保持原始显示范围；图像分辨率和显示降采样可能影响细节判读。FS / 相对 dBFS 不等于绝对声压；未采集频带不解释为零能量。</p>";
 }
 html+="<p align='center'><b>—— 本报告结束 ——</b></p></body></html>";
 QTextDocument document;QFont font = QGuiApplication::font();font.setPointSize(10);document.setDefaultFont(font);document.setDocumentMargin(0);const double scale=96.0/25.4;const QSizeF page(210*scale,297*scale);const double margin=16*scale,header=12*scale,footer=12*scale;QSizeF content(page.width()-2*margin,page.height()-2*margin-header-footer);document.setPageSize(content);document.setHtml(html);int count=document.pageCount();if(count<1||count>120)return 6;
 QDir().mkpath(directory);auto temp=directory+"/report-building.pdf";QPdfWriter writer(temp);writer.setResolution(96);writer.setPageSize(QPageSize(QPageSize::A4));writer.setPageMargins(QMarginsF(0,0,0,0));writer.setTitle("设备运行声学特征与异常评价报告 "+snapshot.value("id").toString());writer.setCreator("现场巡检助手 "+snapshot.value("application_version").toString());QPainter pdf(&writer);if(!pdf.isActive())return 7;
 auto paint=[&](QPainter &p,int pageIndex){p.save();p.setFont(QFont(QGuiApplication::font().family(),8));p.setPen(QColor("#526277"));p.drawText(QRectF(margin,margin-10,page.width()-2*margin,header),Qt::AlignLeft|Qt::AlignVCenter,snapshot.value("id").toString()+" / V"+snapshot.value("revision").toString()+"    "+(snapshot.value("status")=="reviewed"?"已审核":"待审核草稿"));p.drawLine(QPointF(margin,margin+header-4),QPointF(page.width()-margin,margin+header-4));p.drawText(QRectF(margin,page.height()-margin-footer+4,page.width()-2*margin,footer),Qt::AlignCenter,QString("第 %1 / %2 页 · 设备运行声学特征与异常评价").arg(pageIndex+1).arg(count));p.translate(margin,margin+header);p.setClipRect(QRectF(QPointF(0,0),content));p.translate(0,-pageIndex*content.height());QAbstractTextDocumentLayout::PaintContext ctx;ctx.clip=QRectF(0,pageIndex*content.height(),content.width(),content.height());document.documentLayout()->draw(&p,ctx);p.restore();};
 for(int i=0;i<count;++i){if(i&&!writer.newPage())return 8;paint(pdf,i);QImage image(qCeil(page.width()*1.25),qCeil(page.height()*1.25),QImage::Format_RGB32);image.fill(Qt::white);QPainter pix(&image);pix.scale(1.25,1.25);paint(pix,i);pix.end();if(!image.save(directory+QString("/page-%1.png").arg(i+1,3,10,QChar('0'))))return 9;}
 pdf.end();QVariantList pages;for(auto name:QDir(directory).entryList({"page-*.png"},QDir::Files,QDir::Name))pages<<QVariantMap{{"file",name},{"sha256",hash(directory+"/"+name)}};QSaveFile pageManifest(directory+"/page-manifest.json");if(!pageManifest.open(QIODevice::WriteOnly))return 11;pageManifest.write(QJsonDocument::fromVariant(pages).toJson());if(!pageManifest.commit())return 12;QFile::remove(directory+"/report.pdf");if(!QFile::rename(temp,directory+"/report.pdf"))return 10;QFile::setPermissions(directory+"/report.pdf",QFile::ReadOwner|QFile::WriteOwner);return 0;
