// Reuse the application's C++ MATLAB-style painter for report charts, off the UI thread/process.
#include "../ui/NativeHeatmapItem.h"
int renderAcousticCharts(const QString &plots,const QString &directory){
 QFile input(plots);if(!input.open(QIODevice::ReadOnly)||input.size()>96*1024*1024)return 20;auto value=QJsonDocument::fromJson(input.readAll()).toVariant().toMap();auto charts=value.value("charts").toList();if(charts.isEmpty()||charts.size()>24)return 21;
 QVariantList images,batches;int figure=0;QVector<QImage> rendered;
 for(auto v:charts){auto c=v.toMap();auto panels=c.value("panels").toList();if(panels.isEmpty()||panels.size()>8)return 22;int columns=panels.size()>1?2:1,rows=(panels.size()+columns-1)/columns;QImage image(columns*1120,rows*450,QImage::Format_RGB32);image.fill(Qt::white);QPainter painter(&image);painter.setFont(QFont(QGuiApplication::font().family(),13));
  for(int i=0;i<panels.size();++i){auto panel=panels[i].toMap();painter.save();painter.translate((i%columns)*1120,(i/columns)*450);painter.setPen(QColor("#172132"));painter.drawText(QRect(15,2,1080,34),Qt::AlignVCenter,c.value("title").toString()+" · 通道 "+panel.value("channel").toString());painter.translate(0,38);NativeHeatmapItem item;item.setWidth(1120);item.setHeight(410);item.setMatlabStyle(true);item.setPlotData(panel.value("plot").toMap());auto method=c.value("method").toString();if(method=="fft"||method=="welch"||method=="hilbert"){item.setProperty("manualY",true);item.setProperty("yMinimum",method=="fft"?-120.:-160.);item.setProperty("yMaximum",0.);}else if(method=="time"){double peak=.1;for(auto m:value.value("channel_metrics").toList())peak=qMax(peak,m.toMap().value("peak").toDouble()*1.1);item.setProperty("manualY",true);item.setProperty("yMinimum",-peak);item.setProperty("yMaximum",peak);}item.paint(&painter);painter.restore();}
  painter.end();auto imagePath=directory+QString("/figure-%1.png").arg(++figure,2,10,QChar('0'));if(!image.save(imagePath))return 23;QFile::setPermissions(imagePath,QFile::ReadOwner|QFile::WriteOwner);
  QVariantMap plot{{"title",c["title"]},{"method_id",c["method"]},{"metrics",QVariantMap{}},{"x_label",panels.first().toMap()["plot"].toMap()["xLabel"]},{"y_label",panels.first().toMap()["plot"].toMap()["yLabel"]},{"channel_summaries",c["summaries"]}};
  QVariantMap metadata{{"plot",plot},{"channel","全部 "+value.value("channels").toString()+" 通道"},{"recording",value["record"].toMap()["id"]},{"sample_rate",value["sample_rate"]},{"unit","FS"},{"analysis_scope","整段录音"},{"analysis_start",0},{"analysis_end",value["duration"]},{"captured_at",value["computed_at"]}};
  images<<QVariantMap{{"label",QString::number(figure)},{"title",c["title"]},{"method",c["method"]},{"path",imagePath},{"sha256",hash(imagePath)},{"metadata",metadata}};rendered<<image;
 }
 for(int first=0;first<rendered.size();first+=4){int n=qMin(4,int(rendered.size())-first),columns=n>1?2:1,rows=(n+columns-1)/columns;QImage sheet(columns*1200,rows*820,QImage::Format_RGB32);sheet.fill(Qt::white);QPainter p(&sheet);p.setFont(QFont(QGuiApplication::font().family(),18));p.setRenderHint(QPainter::SmoothPixmapTransform);for(int j=0;j<n;++j){int x=(j%columns)*1200,y=(j/columns)*820;p.setPen(QColor("#172132"));p.drawText(QRect(x+10,y+5,1180,35),"F"+QString::number(first+j+1)+" · "+images[first+j].toMap()["title"].toString());auto im=rendered[first+j].scaled(1180,770,Qt::KeepAspectRatio,Qt::SmoothTransformation);p.drawImage(QPoint(x+(1200-im.width())/2,y+44),im);}p.end();auto path=directory+QString("/visual-%1.png").arg(first/4+1);if(!sheet.save(path))return 24;batches<<QVariantMap{{"path",path},{"first",first+1},{"last",first+n}};}
 value.remove("charts");value.remove("record");value["analysis_data_path"]=plots;value["analysis_data_sha256"]=hash(plots);value["images"]=images;value["vision_batches"]=batches;value["imagePath"]=batches.first().toMap()["path"];value["created_at"]=value["computed_at"];value["context"]="整段录音所有分析方法与所有通道，见逐图元数据。";
 QSaveFile output(directory+"/bundle.json");auto bytes=QJsonDocument::fromVariant(value).toJson(QJsonDocument::Indented);if(!output.open(QIODevice::WriteOnly)||output.write(bytes)!=bytes.size()||!output.commit())return 25;return 0;
}
